def compute(vars):
    single_dip = vars["v1"]
    total_obligations = vars["v2"]

    if total_obligations == 0:
        return None

    portion = single_dip / total_obligations
    return {
        "value": portion,
        "trace": {
            "single_dip_equity_obligations": single_dip,
            "total_bankruptcy_settlement_obligations": total_obligations,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
